mapper.update:
UPDATE apms_test_result_value
SET field_name=#{fieldName}, numeric_value=#{numericValue}, text_value=#{textValue},
    unit=#{unit}, is_derived=#{isDerived}
WHERE id=#{id}

mapper.select:
SELECT COUNT(*) AS count, AVG(v.numeric_value) AS avg_val, STDDEV(v.numeric_value) AS stddev_val FROM apms_test_result_value v JOIN apms_test_result r ON v.result_id = r.id JOIN apms_athlete a ON r.athlete_id = a.athlete_id WHERE r.is_valid = '1' AND r.is_selected = '1' AND v.numeric_value IS NOT NULL AND v.is_derived = '0' AND v.indicator_id = #{indicatorId}
AND a.primary_team_id = #{teamId}
AND a.age_group = #{ageGroup}
AND a.gender = #{gender}
